import 'package:flutter/material.dart';
import '../../data/models/report_chart_model.dart';
class ReportsChartCard extends StatelessWidget { const ReportsChartCard({required this.title, required this.data, super.key}); final String title; final List<ReportChartModel> data; @override Widget build(BuildContext context) { final max = data.fold<double>(0, (m, e) => e.value > m ? e.value : m); return Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title, style: const TextStyle(fontWeight: FontWeight.bold)), const SizedBox(height: 12), if (data.isEmpty) const Text('No data') else ...data.map((e) => Padding(padding: const EdgeInsets.only(bottom: 8), child: Row(children: [SizedBox(width: 90, child: Text(e.label, overflow: TextOverflow.ellipsis)), Expanded(child: LinearProgressIndicator(value: max == 0 ? 0 : e.value / max)), const SizedBox(width: 8), Text(e.value.toStringAsFixed(0))])))]))); } }
